BEGIN TRANSACTION READ ONLY; SET LOCAL statement_timeout='15s'; SELECT clock_timestamp() AS captured_at, current_database() AS database_name, current_user AS current_user_name, session_user AS session_user_name, current_setting('role') AS configured_role, current_setting('transaction_isolation') AS transaction_isolation, pg_get_userbyid(d.datdba) AS database_owner, jsonb_build_object('superuser',r.rolsuper,'inherit',r.rolinherit,'createRole',r.rolcreaterole,'createDatabase',r.rolcreatedb,'canLogin',r.rolcanlogin,'replication',r.rolreplication,'bypassRls',r.rolbypassrls) AS current_role_flags FROM pg_database d JOIN pg_roles r ON r.rolname=current_user WHERE d.datname=current_database(); COMMIT;
